INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CITY_8','Spawn Point');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CITY_9','Deathmatch Arena');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CIV','McPvP - The Endless Lobby');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CIV5','McPvP');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CIV5_HEADING_1','The Endless Lobby');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CIV5_TEXT_1','The match ends. The memories do not.[NEWLINE][NEWLINE]McPvP remembers an early Minecraft multiplayer community through turn-based competition: choosing a kit, racing to the Feast, bringing a flag home and spotting an infiltrator. The Old Guard represents its players, friendships and rivalries rather than a single historical ruler. This is an unofficial fan civilization; no external music or Minecraft textures are included.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CIV_PEDIA','The match ends. The memories do not.[NEWLINE][NEWLINE]McPvP remembers an early Minecraft multiplayer community through turn-based competition: choosing a kit, racing to the Feast, bringing a flag home and spotting an infiltrator. The Old Guard represents its players, friendships and rivalries rather than a single historical ruler. This is an unofficial fan civilization; no external music or Minecraft textures are included.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CLOSE','Close');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_CTF','Capture the Flag');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_DAWN','Welcome back, Old Guard.[NEWLINE][NEWLINE]Lobby One is filling. Someone is choosing Kangaroo. Someone swears Stomper is the only kit worth playing. Beyond spawn lies a world of Feasts, flags and uncertain alliances.[NEWLINE][NEWLINE]Build the Original Server Hub, choose your next match in the Server Browser, and give your players a story worth remembering.[NEWLINE][NEWLINE]The match ends. The memories don''t.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_DEFEAT_1','The match ends. The memories don''t. Thanks for playing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_DUMMY','Server Legacy');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_DUMMY_HELP','Automatically maintained capital Culture or temporary Sabotage effects. Cannot be built or captured.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_ENDERMAGE','Endermage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_ENDERMAGE_HELP','Pull one visible enemy land military unit within two tiles onto a legal empty adjacent land tile. Consumes movement. Seven-turn cooldown.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_FINAL','Final Battle');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_FINAL_HELP','+20% combat XP after the Feast activates, until the match ends.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_FLAG','Flag Carrier');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_FLAG_HELP','Carrying an enemy flag: cannot initiate attacks; -15% defensive Combat Strength. Return it on land belonging to one of your cities. Embarking or changing ownership loses the flag; ordinary upgrade, gift and disband commands are blocked.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_GRACE','Grace Period');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_GRACE_HELP','+10% defensive Combat Strength during the opening phase of Hardcore Games.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_GREETING_1','Welcome to the lobby. Pick a kit, learn the map, and make yourself a name.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_HG','Hardcore Games');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_HUB','Original Server Hub');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_HUB_HELP','Replaces Barracks and retains its active benefits. +1 Culture and +1 Gold. Eligible military units trained or purchased here may select a kit and grant +2 Server Legacy once.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_HUB_PEDIA','A few blocks, a sign and a familiar crowd: a whole world begins in the lobby. The Original Server Hub trains competitors and records their first steps into the arena.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_HUB_STRATEGY','Build Hubs in military training cities to unlock kits and steadily earn Legacy. Free, captured and upgraded units do not grant training Legacy.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_INFILTRATE','Infiltrate');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_KANGAROO','Kangaroo');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_KANGAROO_HELP','+1 land Movement; -10% defensive Combat Strength.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_LEADER','The Old Guard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_LEADER_PEDIA','The Old Guard is the player who knows every route out of spawn and still makes room for a beginner in the lobby. Competitive, adaptable and opportunistic, they build a legacy through skill and participation. Their story belongs to all who returned for just one more game.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_LOCATE','Locate Feast');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_MEMORY','Legacy Unforgotten');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_MEMORY_HELP','Permanent +10% military combat XP. The servers fall silent; the memories remain.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_OLD_GUARD','The Old Guard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_OLD_GUARD_HEADING_1','A Legacy Shared');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_OLD_GUARD_LIVED','The age of the crowded lobby');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_OLD_GUARD_NAME','The Old Guard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_OLD_GUARD_SUBTITLE','Just One More Game');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_OLD_GUARD_TEXT_1','The Old Guard is the player who knows every route out of spawn and still makes room for a beginner in the lobby. Competitive, adaptable and opportunistic, they build a legacy through skill and participation. Their story belongs to all who returned for just one more game.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_OLD_GUARD_TITLES_1','Keeper of the Server');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_PANEL_HELP','Select a military unit on the map. Choose a kit or cycle valid targets, then use its action. All durations scale with game speed. Queued modes begin next match. Target buttons show why an action is unavailable.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_PEACE_1','Good game. Same lobby next time?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_POISON','Viper Poison');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_POISON_HELP','5 damage at the start of each of the next two owner turns. Further Viper attacks refresh the duration without stacking.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_QUEUE_CTF','Queue Capture the Flag');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_QUEUE_HG','Queue Hardcore Games');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_QUEUE_SAB','Queue Sabotage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_REMEMBRANCE','Legacy Unforgotten[NEWLINE][NEWLINE]The servers have fallen silent.[NEWLINE][NEWLINE]The lobbies that once held thousands now stand empty.[NEWLINE][NEWLINE]But the friendships, rivalries, victories and defeats remain.[NEWLINE][NEWLINE]A match can end.[NEWLINE][NEWLINE]A memory doesn''t have to.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_RETURN','Return flag');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SAB','Sabotage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SHORT','McPvP');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_1','Spectator');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_10','Last Login');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_2','Hidden Name');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_3','Night Shift');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_4','Quiet Lobby');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_5','False Team');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_6','Back Route');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_7','Disguise');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_8','Watchtower');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_SPY_9','Old Rival');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_STEAL','Steal flag');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_STOMPER','Stomper');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_STOMPER_HELP','From a hill, deal 20 damage to one adjacent visible enemy land military unit on flat ground. Consumes movement. Five-turn cooldown.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_STRATEGY','Preserve your Veterans and select kits for the terrain. Kangaroo excels at flags; Stomper controls hills; Endermage disrupts formations; Thor punishes exposed units; Viper rewards repeated skirmishing. Hubs preserve Barracks benefits and train kit-ready armies. Queue objectives your position can support. Culture comes from participation, not idle conquest.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_TARGET','Next target');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_THANKS','THANKS FOR PLAYING');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_THOR','Thor');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_THOR_HELP','Deal 15 damage to one visible enemy military unit within two tiles. Consumes movement. Five-turn cooldown.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_TRAIT','Just One More Game');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_TRAIT_HELP','Queue Hardcore Games, Capture the Flag or Sabotage in the Server Browser. Matches last 20 turns on Standard speed. Earn Server Legacy from contested Feasts, returned flags, infiltration and Server Hub training. Every 25 Lifetime Legacy grants +1 capital Culture (maximum +8). In the Information Era, Legacy Unforgotten grants permanent +10% military combat XP and up to +10 additional capital Culture. Five mutually exclusive kits give units distinct tactical abilities.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_UNIT','Veteran PvPer');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_UNIT_HELP','Replaces Scout: 6 Combat Strength, normal active Scout mobility and reconnaissance, +25% combat XP. Select a kit immediately. Change kits in a friendly city every 15 turns; identity and cooldowns survive normal upgrades.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_UNIT_PEDIA','Every expert was once the beginner at spawn. Veteran PvPers carry the lessons of countless matches into new eras; their battlefield model and normal upgrade path follow the active Scout.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_UNIT_STRATEGY','Scout, survive and adapt. Veterans keep their identity and kit privileges after upgrades. Kit changes consume movement and preserve outstanding ability cooldowns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_VETERAN','Old Guard Veteran');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_VETERAN_HELP','+25% combat XP; kit eligibility and city retraining survive upgrades.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_VIPER','Viper');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_VIPER_HELP','Direct attacks that damage an enemy military unit poison it for 5 damage at the start of its next two turns. Refreshes; never stacks.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_MCPVP_WAR_1','Grace period is over. See you at the Feast.');
